from typing import List

class Solution:
    def minDeletionSize(self, A: List[str]) -> int:
        if not A:
            return 0

        n_cols = len(A[0])
        keep = [True] * n_cols

        for col in range(n_cols):
            if not keep[col]:
                continue
            for next_col in range(col + 1, n_cols):
                if not keep[next_col]:
                    continue
                conflict = False
                for row in range(len(A)):
                    if A[row][col] > A[row][next_col]:
                        conflict = True
                        break
                if conflict:
                    keep[next_col] = False

        return sum(1 for k in keep if not k)
